#ifndef TZRULES_H
#define TZRULES_H

// The POSIX TZ rule of an IANA zone: "Europe/Rome" gives
// "CET-1CEST,M3.5.0,M10.5.0/3". Set as TZ, the rule alone lets the C library
// move between standard time and daylight saving on the right days, with no
// zone files on the device.
//
// tzrules.c is generated by tools/tz_rules.py from the tz database.

// The rule, or NULL for a name the table does not know.
const char *tzrules_lookup(const char *zone);

#endif /* TZRULES_H */
